/* ==================================================================
   swagui — design tokens

   Requires Tailwind CSS v4 and React 19.

   Import once, after Tailwind:

     @import "tailwindcss";
     @import "./swagui.css";

   Everything below is a knob. A project overrides whichever it cares
   about in its own :root and leaves the rest. Nothing here is a preset;
   the permutation is the theme.
   ================================================================== */

/* Enter/exit animations for dialog, popover, dropdown, sheet, tooltip and
   friends. Shipped here so an install is not silently missing them. */
@import "tw-animate-css";

/* Dark mode is class-driven: put `dark` on <html> or any wrapper. Without
   this variant every dark: utility in every component is a no-op. */
@custom-variant dark (&:is(.dark *));

@theme inline {
  --color-background: var(--background);
  --color-foreground: var(--foreground);
  --color-card: var(--card);
  --color-card-foreground: var(--card-foreground);
  --color-popover: var(--popover);
  --color-popover-foreground: var(--popover-foreground);
  --color-primary: var(--primary);
  --color-primary-foreground: var(--primary-foreground);
  --color-secondary: var(--secondary);
  --color-secondary-foreground: var(--secondary-foreground);
  --color-muted: var(--muted);
  --color-muted-foreground: var(--muted-foreground);
  --color-accent: var(--accent);
  --color-accent-foreground: var(--accent-foreground);
  --color-destructive: var(--destructive);
  --color-border: var(--border);
  --color-input: var(--input);
  --color-ring: var(--ring);
  --color-brand: var(--brand);
  --color-brand-content: var(--brand-content);
  --color-chart-1: var(--chart-1);
  --color-chart-2: var(--chart-2);
  --color-chart-3: var(--chart-3);
  --color-chart-4: var(--chart-4);
  --color-chart-5: var(--chart-5);

  --font-sans: var(--font-body);
  --font-mono: var(--font-mono-face);

  /* The radius ladder is multiplicative, not additive. One factor scales
     every step proportionally, so corners stay optically consistent across
     sizes instead of drifting toward square at small radii. */
  --radius-sm: calc(0.375rem * var(--squircle-factor));
  --radius-md: calc(0.5rem * var(--squircle-factor));
  --radius-lg: calc(0.75rem * var(--squircle-factor));
  --radius-xl: calc(1rem * var(--squircle-factor));
  --radius-2xl: calc(1.5rem * var(--squircle-factor));

  /* [.22,1,.36,1] is the house curve: a firm ease-out that settles rather
     than snaps. Durations run slower than Tailwind's 150ms default; that
     slowness is most of the "considered" read. */
  --ease-swagui: cubic-bezier(0.22, 1, 0.36, 1);
  --ease-out-expo: cubic-bezier(0.16, 1, 0.3, 1);
  --duration-press: 120ms;
  --duration-fast: 180ms;
  --duration-base: 260ms;
  --duration-slow: 420ms;
}

/* ---------------- Knobs ---------------- */

:root {
  /* Type. Wire these to real faces in your app (next/font, @font-face…).
     Left unset they fall back to the system stack. */
  --font-display: var(--font-body);
  --font-body: ui-sans-serif, system-ui, sans-serif;
  --font-mono-face: ui-monospace, SFMono-Regular, monospace;
  --display-tracking: -0.03em;

  /* Geometry. 1 gives stock Tailwind corners. */
  --squircle-factor: 1.4;
  --radius: calc(0.625rem * var(--squircle-factor));

  /* Brand — the one hot colour. It is deliberately withheld from buttons
     and component surfaces; it appears on links, focus rings, status dots
     and glows only. --brand-content is the darker step for text on light. */
  --brand: oklch(0.58 0.16 250);
  --brand-content: oklch(0.5 0.16 250);

  /* Canvas. Default is a warm off-white ground under faintly cool ink;
     set data-canvas="white" or "grey" on a wrapper to change it. */
  --background: oklch(0.995 0.004 85);
  --foreground: oklch(0.2 0.012 260);
  --card: oklch(0.998 0.003 85);
  --muted-foreground: oklch(0.556 0 0);

  /* Derived. These follow --background/--foreground, so a canvas change
     propagates without redefining anything below. */
  --card-foreground: var(--foreground);
  --popover: var(--card);
  --popover-foreground: var(--foreground);
  --primary: var(--foreground);
  --primary-foreground: var(--background);
  --secondary: color-mix(in oklch, var(--foreground) 6%, transparent);
  --secondary-foreground: var(--foreground);
  --muted: color-mix(in oklch, var(--foreground) 5%, transparent);
  /* NOTE: --accent keeps shadcn semantics — a neutral hover fill, not a hue.
     The hot colour is --brand. Mapping the brand here would turn every
     hover state in every component the brand colour. */
  --accent: color-mix(in oklch, var(--foreground) 6%, transparent);
  --accent-foreground: var(--foreground);
  --border: color-mix(in oklch, var(--foreground) 8%, transparent);
  --input: color-mix(in oklch, var(--foreground) 10%, transparent);
  --ring: color-mix(in oklch, var(--brand) 55%, transparent);

  --destructive: oklch(0.55 0.2 27);
  --success: oklch(0.55 0.13 155);
  --warning: oklch(0.68 0.14 75);

  --chart-1: oklch(0.646 0.222 41.116);
  --chart-2: oklch(0.6 0.118 184.704);
  --chart-3: oklch(0.398 0.07 227.392);
  --chart-4: oklch(0.828 0.189 84.429);
  --chart-5: oklch(0.769 0.188 70.08);
}

.dark {
  --background: oklch(0.15 0.008 260);
  --foreground: oklch(0.94 0.008 80);
  --card: oklch(0.21 0.008 260);
  --muted-foreground: oklch(0.68 0 0);
  --brand: oklch(0.7 0.14 250);
  --brand-content: oklch(0.7 0.14 250);
  --destructive: oklch(0.68 0.18 25);
  --success: oklch(0.72 0.12 155);
  --warning: oklch(0.78 0.13 78);
}

/* ---------------- Canvas variants ---------------- */

[data-canvas="white"] {
  --background: oklch(1 0 0);
  --foreground: oklch(0.18 0 0);
  --card: oklch(1 0 0);
}

[data-canvas="grey"] {
  --background: oklch(0.965 0 0);
  --foreground: oklch(0.18 0 0);
  --card: oklch(1 0 0);
}

.dark[data-canvas="white"],
.dark [data-canvas="white"],
.dark[data-canvas="grey"],
.dark [data-canvas="grey"] {
  --background: oklch(0.145 0 0);
  --foreground: oklch(0.97 0 0);
  --card: oklch(0.205 0 0);
}

/* ---------------- Surface recipes ----------------

   The surface knob swaps the shadow tokens themselves, so all components
   follow automatically — no per-component class is involved. */

:root,
[data-surface="elevation"] {
  --shadow-hairline: 0 0 0 0.5px color-mix(in oklch, var(--foreground) 12%, transparent);
  --shadow-raised:
    0 1px 2px rgb(0 0 0 / 0.035), 0 3px 8px rgb(0 0 0 / 0.035), 0 8px 28px rgb(0 0 0 / 0.045);
  --shadow-overlay:
    0 1px 2px rgb(0 0 0 / 0.04), 0 4px 12px rgb(0 0 0 / 0.05), 0 16px 48px rgb(0 0 0 / 0.06);
  --inset-highlight: inset 0 1px 1px rgb(255 255 255 / 0.8);
}

[data-surface="bevel"] {
  --shadow-hairline: 0 0 0 0.5px color-mix(in oklch, var(--foreground) 18%, transparent);
  --shadow-raised:
    0 0 0 0.5px color-mix(in oklch, var(--foreground) 18%, transparent),
    0 4px 6px -1px rgb(0 0 0 / 0.05), 0 2px 4px -2px rgb(0 0 0 / 0.05);
  --shadow-overlay:
    0 0 0 0.5px color-mix(in oklch, var(--foreground) 18%, transparent),
    0 12px 32px -8px rgb(0 0 0 / 0.12);
  --inset-highlight: inset 0 0 0 1px color-mix(in oklch, white 70%, transparent);
}

[data-surface="glass"] {
  --shadow-hairline: 0 0 0 1px color-mix(in oklch, var(--foreground) 8%, transparent);
  --shadow-raised:
    0 10px 30px -10px color-mix(in oklch, var(--foreground) 12%, transparent),
    inset 0 1px 1px color-mix(in oklch, var(--foreground) 10%, transparent);
  --shadow-overlay:
    0 16px 48px -12px color-mix(in oklch, var(--foreground) 18%, transparent),
    inset 0 1px 1px color-mix(in oklch, var(--foreground) 12%, transparent);
  --inset-highlight: inset 0 1px 1px color-mix(in oklch, var(--foreground) 10%, transparent);
}

.dark {
  --inset-highlight: inset 0 1px 1px rgb(255 255 255 / 0.06);
}

/* ---------------- Density scope ----------------

   Every Tailwind spacing utility compiles to calc(var(--spacing) * n) —
   p-*, m-*, gap-*, h-*, w-*, size-*. So overriding --spacing on a subtree
   retunes padding, margins, gaps, control heights and icon sizes across
   every component at once, with no per-component work.

   Line-height comes from the --text-*--line-height pair variables, so those
   are tightened explicitly. Colour is untouched: density never alters the
   palette.

   Usage: <div data-density="compact"> around an app shell, or on one table. */

[data-density="compact"] {
  --spacing: 0.2rem;
  --squircle-factor: 1.1;
  --text-xs--line-height: 1.3;
  --text-sm--line-height: 1.35;
  --text-base--line-height: 1.4;
  --text-lg--line-height: 1.35;
  --text-xl--line-height: 1.3;
  --text-2xl--line-height: 1.2;
}

[data-density="comfortable"] {
  --spacing: 0.25rem;
}

/* ---------------- Base ---------------- */

@layer base {
  * {
    @apply border-border outline-ring/50;
  }

  body {
    @apply bg-background text-foreground;
    font-family: var(--font-body);
    -webkit-font-smoothing: antialiased;
  }

  /* 2px icon strokes read chunky against 0.5px hairlines and 4% shadows.
     CSS beats Lucide's inline stroke-width attribute, so this retunes every
     icon in the system from one rule. */
  svg.lucide {
    stroke-width: 1.5;
  }

  /* Display type runs tight, and the tightening scales with size. */
  h1,
  h2,
  h3,
  h4,
  h5,
  h6 {
    font-family: var(--font-display);
  }
  h1,
  h2,
  h3 {
    letter-spacing: var(--display-tracking);
  }
  h4,
  h5,
  h6 {
    letter-spacing: calc(var(--display-tracking) * 0.66);
  }
}

/* ---------------- Brand utilities ----------------

   The only places the hot colour is allowed. */

@layer components {
  .brand-link {
    color: var(--brand-content);
    text-decoration: underline;
    text-decoration-style: dotted;
    text-underline-offset: 3px;
    text-decoration-color: color-mix(in oklch, var(--brand) 40%, transparent);
  }

  .brand-dot {
    background: var(--brand);
    box-shadow: 0 0 0 3px color-mix(in oklch, var(--brand) 15%, transparent);
  }

  .brand-glow {
    box-shadow:
      0 0 36px 2px color-mix(in oklch, var(--brand) 8%, transparent),
      0 8px 50px 6px color-mix(in oklch, var(--brand) 5%, transparent);
  }
}
